// @generated by:gauntlet run:godseye-local-jobs
import { randomUUID } from "node:crypto";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { type JobsFixture, jobsFixture } from "./jobs-helpers.js";

describe("T20 cell isolation and recovery hold", () => {
  let fixture: JobsFixture;
  beforeEach(async () => {
    fixture = await jobsFixture();
  });
  afterEach(async () => {
    await fixture.store.close();
  });
  const otherCell = () => {
    const environment = fixture.secondProject.environments.find(
      (item) => item.kind === "development",
    );
    if (!environment) throw new Error("Second cell fixture missing");
    return environment;
  };
  const registerOther = (name = "on-signup") =>
    fixture.jobs().registerDefinition(
      fixture.freshOwner(),
      {
        projectId: fixture.secondProject.id,
        environmentId: otherCell().id,
        expectedEnvironmentRevision: otherCell().revision,
        name,
        handler: "fixture.other",
        trigger: { kind: "event", eventType: "user.signup" },
        effectPolicy: "idempotent",
        limits: { maxConcurrent: 1, maxAttempts: 1, timeoutSeconds: 30, retentionDays: 7 },
      },
      randomUUID(),
    );
  const service = () => ({
    id: "cell-a-service",
    kind: "service" as const,
    projectIds: [fixture.project.id],
  });

  it("routes an event only to definitions in the exact project and environment", async () => {
    await fixture.register({
      name: "on-signup",
      trigger: { kind: "event", eventType: "user.signup" },
    });
    await registerOther();
    const runs = await fixture.jobs().ingestEvent(service(), {
      projectId: fixture.project.id,
      environmentId: fixture.development.id,
      eventType: "user.signup",
      eventId: "evt-isolation-01",
    });
    expect(runs).toHaveLength(1);
    await fixture.work();
    expect(fixture.handler.calls).toHaveLength(1);
    expect(fixture.other.calls).toHaveLength(0);
  });
  it("refuses events that claim another project or an environment from another project", async () => {
    await registerOther();
    const event = {
      eventType: "user.signup",
      eventId: "evt-isolation-02",
    };
    await expect(
      fixture.jobs().ingestEvent(service(), {
        ...event,
        projectId: fixture.secondProject.id,
        environmentId: otherCell().id,
      }),
    ).rejects.toMatchObject({ code: "FORBIDDEN" });
    await expect(
      fixture.jobs().ingestEvent(service(), {
        ...event,
        projectId: fixture.project.id,
        environmentId: otherCell().id,
      }),
    ).rejects.toMatchObject({ code: "FORBIDDEN" });
    expect(
      await fixture
        .jobs()
        .overview(fixture.freshOwner())
        .then((view) => view.runs),
    ).toHaveLength(0);
  });
  it("denies a service actor every owner job operation", async () => {
    const definition = await fixture.register();
    const actor = service();
    await expect(
      fixture
        .jobs()
        .trigger(
          actor,
          definition.id,
          { expectedRevision: 0, dedupeKey: "service-key-1" },
          randomUUID(),
        ),
    ).rejects.toMatchObject({ code: "FORBIDDEN" });
    await expect(fixture.jobs().pause(actor, definition.id, 0, randomUUID())).rejects.toMatchObject(
      { code: "FORBIDDEN" },
    );
  });
  it("refuses a scheduler plan that references a definition of another cell", async () => {
    const foreign = await registerOther("foreign-job");
    await expect(
      fixture.infrastructure.foundation.createPlan(
        { id: "jobs-scheduler", kind: "service", projectIds: [fixture.project.id] },
        {
          projectId: fixture.project.id,
          environmentId: fixture.development.id,
          targetId: fixture.development.id,
          expectedRevision: fixture.project.revision,
          adapterId: "local.jobs",
          command: { kind: "job.operation", intent: "trigger", definitionRef: foreign.id },
          maxCostMicros: 0,
          tools: ["job.run"],
          destinations: ["jobs.local"],
        },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ code: "FORBIDDEN" });
  });
  it("keeps equal effect keys in different cells as separate intents", async () => {
    const key = "shared-effect-key";
    await fixture.jobs().transact(async (tx) => {
      await fixture.jobs().enqueueOutbox(tx, fixture.intent(key));
      await fixture.jobs().enqueueOutbox(tx, {
        ...fixture.intent(key),
        projectId: fixture.secondProject.id,
        environmentId: otherCell().id,
      });
    });
    await fixture.jobs().tick();
    expect(await fixture.outboxRows()).toHaveLength(2);
    expect(fixture.sender.sends.map((send) => send.projectId).sort()).toEqual(
      [fixture.project.id, fixture.secondProject.id].sort(),
    );
  });
  it("rejects outbox intent that forges a cell or run from another project", async () => {
    const definition = await fixture.register();
    const run = await fixture.trigger(definition.id, 0, "forge-run-00001");
    await expect(
      fixture.jobs().transact((tx) =>
        fixture.jobs().enqueueOutbox(tx, {
          ...fixture.intent("forged-intent-1"),
          projectId: fixture.secondProject.id,
        }),
      ),
    ).rejects.toMatchObject({ code: "FORBIDDEN" });
    await expect(
      fixture.jobs().transact((tx) =>
        fixture.jobs().enqueueOutbox(tx, {
          ...fixture.intent("forged-intent-2"),
          projectId: fixture.secondProject.id,
          environmentId: otherCell().id,
          jobRunId: run.id,
        }),
      ),
    ).rejects.toMatchObject({ code: "FORBIDDEN" });
  });
  it("persists legitimate cell work across an engine restart", async () => {
    const definition = await fixture.register();
    await fixture.trigger(definition.id, 0, "persist-key-001");
    const restarted = fixture.build();
    const view = await restarted.jobs.overview(fixture.freshOwner());
    expect(view.definitions.map((item) => item.id)).toEqual([definition.id]);
    expect(view.runs).toHaveLength(1);
  });

  const hold = (value: boolean) =>
    fixture.store.db
      .update(schema.environments)
      .set({ recoveryHold: value })
      .where(eq(schema.environments.id, fixture.development.id));
  it("parks outbox intent as held in a recovery cell and requires an owner decision to release it", async () => {
    await fixture
      .jobs()
      .transact((tx) => fixture.jobs().enqueueOutbox(tx, fixture.intent("held-intent-001")));
    await hold(true);
    await fixture.jobs().tick();
    const [parked] = await fixture.outboxRows();
    expect(parked?.state).toBe("held");
    expect(fixture.sender.sends).toHaveLength(0);
    await hold(false);
    await fixture.jobs().tick();
    expect(fixture.sender.sends).toHaveLength(0);
    const overview = await fixture.jobs().overview(fixture.freshOwner());
    expect(overview.outbox[0]?.state).toBe("held");
    await fixture.jobs().reconcileOutbox(
      fixture.freshOwner(),
      parked?.id ?? "",
      {
        expectedState: "held",
        resolution: "observed_absent_retry",
        evidenceRef: "operator:hold-released",
      },
      randomUUID(),
    );
    await fixture.jobs().tick();
    expect((await fixture.outboxRows())[0]?.state).toBe("delivered");
  });
  it("blocks scheduling, dispatch and triggers while the cell is held and reports it in the overview", async () => {
    const cron = await fixture.register({ trigger: { kind: "cron", cron: "*/5 * * * *" } });
    const manual = await fixture.register({ name: "manual-job" });
    const queued = await fixture.trigger(manual.id, 0, "held-queued-0001");
    await hold(true);
    fixture.clock.advance(10 * 60_000);
    const tick = await fixture.jobs().tick();
    expect(tick).toMatchObject({ scheduled: 0, dispatched: 0 });
    expect((await fixture.state(queued.id)).runId).toBeNull();
    await expect(fixture.trigger(manual.id, 0, "held-queued-0002")).rejects.toMatchObject({
      code: "RECOVERY_HOLD",
    });
    const overview = await fixture.jobs().overview(fixture.freshOwner());
    expect(overview.engine.heldEnvironmentIds).toContain(fixture.development.id);
    await hold(false);
    await fixture.work();
    expect((await fixture.state(queued.id)).state).toBe("succeeded");
    expect(cron.revision).toBe(0);
  });
  it("blocks work in a suspended project", async () => {
    const definition = await fixture.register();
    const run = await fixture.trigger(definition.id, 0, "suspended-0001");
    await fixture.store.db
      .update(schema.projects)
      .set({ status: "suspended" })
      .where(eq(schema.projects.id, fixture.project.id));
    await fixture.jobs().tick();
    expect((await fixture.state(run.id)).runId).toBeNull();
    await expect(fixture.trigger(definition.id, 0, "suspended-0002")).rejects.toMatchObject({
      code: "PROJECT_SUSPENDED",
    });
  });
  it("blocks work in an expired preview environment", async () => {
    const definition = await fixture.register();
    const run = await fixture.trigger(definition.id, 0, "expired-key-001");
    await fixture.store.db
      .update(schema.environments)
      .set({ kind: "preview", expiresAt: new Date(fixture.clock.now().getTime() - 1000) })
      .where(eq(schema.environments.id, fixture.development.id));
    await fixture.jobs().tick();
    expect((await fixture.state(run.id)).runId).toBeNull();
  });
});
